var Userconnection = Get<UserConnection>("UserConnection");
string soId = Get<string>("SOID");
string deviceList = Get<string>("DeviceList");
string offerList = Get<string>("OfferIDList");
string jsonReq = Get<string>("JSONRequest");
string reservationId = Get<string>("ReservationId");
bool forERP = Get<bool>("ForERP");

var createProduct = new CreateProduct(UserConnection);
var service = new DMSService(UserConnection);

try {
	if (!string.IsNullOrEmpty(jsonReq)) {
		var jsonSettings = new JsonSerializerSettings {
			DateParseHandling = DateParseHandling.None
		};
		var param = JsonConvert.DeserializeObject<CreateProductRequest>(jsonReq, jsonSettings);
		Set("RequestBody", JsonConvert.SerializeObject(param, Formatting.Indented));

		var response = service.CreateProduct(param).GetAwaiter().GetResult();
		Set("ResponseBody", JsonConvert.SerializeObject(response, Formatting.Indented));
	}
	else if (!string.IsNullOrEmpty(deviceList) && !string.IsNullOrEmpty(offerList)) {
		List<string> devices = deviceList.Split(',').ToList();
		List<string> offerIds = offerList.Split(',').ToList();
		List<DeviceItem> deviceItemList = devices.Select((item, index) => new DeviceItem {
			DeviceID = item,
			OfferID = offerIds[index]
		}).ToList();

		var request = createProduct.GetParam(reservationId, soId, deviceItemList);
		Set("RequestBody", JsonConvert.SerializeObject(request, Formatting.Indented));

		var response = service.CreateProduct(request).GetAwaiter().GetResult();
		Set("ResponseBody", JsonConvert.SerializeObject(response, Formatting.Indented));
	} else {
		var request = forERP ? createProduct.GetParamERP(soId) : createProduct.GetParam(soId);
		Set("RequestBody", JsonConvert.SerializeObject(request, Formatting.Indented));

		var response = service.CreateProduct(request).GetAwaiter().GetResult();
		Set("ResponseBody", JsonConvert.SerializeObject(response, Formatting.Indented));
	}
} catch (Exception e) {
	Set("Message", e.Message);
}

return true;
